package main
import (
  "sync"
  "sync/atomic"
)
func main() {
  var counter atomic.Int64
  var wg sync.WaitGroup
  wg.Add(100)
  for i := 0; i < 100; i++ {
    go func() {
      counter.Add(1)
      wg.Done()
    }()
  }
  wg.Wait()
  println(counter.Load())
}
